def build_concept_story():
    entries=[x for c in CHAPTERS for x in c[2]]
    tabs=[];panels=[];options=[]
    for i,((original,headline,copy),(slug,label,photo,alt,vision,drawing)) in enumerate(zip(entries,SCENES)):
        tabs.append(f'<button role="tab" id="studio-tab-{i}" aria-controls="studio-panel-{i}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}" data-concept="{slug}"><span class="studio-tab-number">{i+1:02}</span><span>{escape(label)}</span><span class="studio-tab-arrow" aria-hidden="true">↗</span></button>')
        options.append(f'<option value="{i}">{i+1:02} · {escape(label)}</option>')
        group=CHAPTERS[i//3][1]
        art=f'<svg viewBox="0 0 330 280" aria-hidden="true" class="studio-diagram">{drawing}</svg>'
        panels.append(f'<section role="tabpanel" id="studio-panel-{i}" aria-labelledby="studio-tab-{i}" class="studio-panel theme-{slug}"'+(' hidden' if i else '')+f'><div class="studio-visual"><div class="studio-blueprint" aria-hidden="true"></div><span class="studio-scene-word" aria-hidden="true">{escape(slug.split("-")[0])}</span><figure class="studio-photo"><img src="../assets/images/photos/{photo}" alt="{escape(alt)}" loading="lazy"><figcaption>Life at River Tech · Post Falls</figcaption></figure><div class="studio-sketch">{art}</div></div><div class="studio-copy"><span class="eyebrow">{escape(group)}</span><h4>{escape(headline)}</h4><p class="studio-vision">{escape(vision)}</p><p>{escape(copy)}</p><div class="studio-bottom"><span>{escape(original)}</span><a href="contact.html?topic=school">Imagine this in your school <span aria-hidden="true">↗</span></a></div></div></section>')
    return '<div class="concept-studio" id="school-concepts" data-concept-studio><header class="studio-intro"><div><span class="eyebrow">Explore the River Tech model</span><h3>A school built for<br><em>what comes next.</em></h3></div><p>Twelve ideas. Countless possibilities for your community. Step inside the school you could build—one discovery at a time.</p></header><div class="studio-shell"><div class="studio-toolbar"><span><i aria-hidden="true"></i> THE SCHOOL YOU COULD BUILD</span><div class="studio-controls"><button type="button" data-studio-prev aria-label="Previous concept">←</button><span data-studio-count aria-live="polite">01 / 12</span><button type="button" data-studio-next aria-label="Next concept">→</button></div></div><div class="studio-layout"><nav class="studio-nav" aria-label="Twelve school concepts"><div class="studio-nav-caption">Choose a possibility</div><label class="studio-mobile-label" for="studio-picker">Explore the twelve concepts</label><select id="studio-picker" class="studio-picker">'+''.join(options)+'</select><div class="studio-tabs" role="tablist" aria-label="Explore the twelve school concepts">'+''.join(tabs)+'</div></nav><div class="studio-stage">'+''.join(panels)+'</div></div><div class="studio-progress" aria-hidden="true"><span></span></div></div><div class="studio-footer"><p>A place to discover their gifts.<br><strong>A foundation to do something with them.</strong></p><a class="text-link" href="contact.html?topic=school">Let’s build it in your community <span aria-hidden="true">↗</span></a></div></div>'
